fn handle_chat(self, version, rnd, player, data, from: Position, chat: &Chat, misunderstood: bool, debug)

// chat.rs:9 — 자기 자신이 보낸 콜은 무시
if from == player.info.position { return; }        // Position::eq 인라인(entity.rs:563), player+0x9c0

let ctx  = data.context;                            // OperationData+0x8 → &GameContext
let tut  = ctx.tutorial;                            // GameContext+0x38, TutorialType(u8)

// chat.rs:12 — rule_scope::position_exists(ctx, from) 인라인(rule_scope.rs:36~41)
//   "이 튜토리얼 모드에 그 포지션의 아군이 실제로 존재하는가"
let exists = match from {
  Top(0)                 => matches!(tut, None(0) | TopSolo(2) | Line(7) | Total(8)),                 // rule_scope.rs:38 (TutorialType::spawn_top_minion 인라인)
  Jungle(1)              => tut == None(0) || tut == JungleOnly(6) || tut >= 8/*Total*/,              // rule_scope.rs:39 (TutorialType::player_count 인라인 후 상수접힘)
  Mid(2)                 => matches!(tut, None(0) | MidSolo(4) | MidBottom(5) | Line(7) | Total(8)),  // rule_scope.rs:40 (spawn_mid_minion 인라인)
  Bottom(3) | Support(4) => matches!(tut, None(0) | First(1) | Bottom(3) | MidBottom(5) | Line(7) | Total(8)), // rule_scope.rs:41 (spawn_bottom_minion 인라인)
};
if !exists { return; }

// chat.rs:12 — 두 번째 게이트(짧은 회로: exists 가 true 일 때만 호출)
if !rule_scope::chat_allowed(ctx, chat) { return; }  // rule_scope.rs:128, 본문 미조사

// chat.rs:18 — TraceLevel::is_enabled() 인라인(trace.rs:14~15)
if ctx.trace_level == Off(0) {
    self.handle_chat_inner(version, rnd, player, data, from, chat, misunderstood, debug); // chat.rs:19 (tail call)
    return;
}

// ── 여기부터 트레이스 ON 경로(chat.rs:22~38) ──
let plan_before      = self.plan.get_name();                       // chat.rs:22, self+0x5e8 (BigPlan 384B)
let objective_before = format!("{:?}", &self.team_plan.objective); // chat.rs:23, self+0x517 (Option<MainObjective>)
self.handle_chat_inner(version, rnd, player, data, from, chat, misunderstood, debug); // chat.rs:24
let plan_after       = self.plan.get_name();                       // chat.rs:25
let objective_after  = format!("{:?}", &self.team_plan.objective); // chat.rs:26

// chat.rs:27~38 — self.pending_trace_events.push(...)  (self+0x858, Vec<PendingTraceEvent>, stride 184)
let tick = (*data.cache.game)[vtable+0x28]();   // chat.rs:28, dyn AbstractGame 슬롯5 → usize
push PendingTraceEvent {
    event: TraceEventType::CallHandled {          // 판별자 store i64 0x800000000000000F
        chat:             format!("{:?}", chat),  // chat.rs:31 → +0x08
        from,                                     // → +0x80
        misunderstood,                            // → +0x84
        plan_before,                              // chat.rs:33 → +0x20
        plan_after,                               // chat.rs:34 → +0x38
        objective_before,                         // chat.rs:35 → +0x50
        objective_after,                          // chat.rs:36 → +0x68
    },
    tick,                                         // → +0xb0
}
// push: len(self+0x868) == cap(self+0x858) 이면 RawVec::grow_one, 그 후 ptr(self+0x860)+len*184 에 184B memcpy, len += 1
return; // chat.rs:39

// 주: unwind 경로(블록 50/54/60/72/100~107)는 이미 만든 String 들을 drop_glue 로 정리하는 정리코드일 뿐 판정과 무관.
